-- The catalogue as the site had it before the admin page (made by tools/seed.mjs).
-- Only fills an empty catalogue, so it never undoes changes made in the admin.
do $$
begin
  if exists (select 1 from public.products) or exists (select 1 from public.categories) then return; end if;
  update public.categories set cover = 'microwave-25l' where key = 'cooking' and exists (select 1 from public.products where id = 'microwave-25l');
  update public.categories set cover = 'blender-3in1' where key = 'prep' and exists (select 1 from public.products where id = 'blender-3in1');
  update public.categories set cover = 'kettle-2585' where key = 'beverage' and exists (select 1 from public.products where id = 'kettle-2585');
  update public.categories set cover = 'cookware-set-16pc' where key = 'cookware' and exists (select 1 from public.products where id = 'cookware-set-16pc');
  update public.categories set cover = 'steam-iron' where key = 'home' and exists (select 1 from public.products where id = 'steam-iron');
end $$;
